class Solution {
    public int numOfPairs(String[] nums,String target){
        Map<String,Integer> frequency=new HashMap<>();
        for(String value:nums)frequency.merge(value,1,Integer::sum);
        int answer=0;
        for(int split=1;split<target.length();split++){
            String left=target.substring(0,split),right=target.substring(split);
            int first=frequency.getOrDefault(left,0),second=frequency.getOrDefault(right,0);
            answer+=left.equals(right)?first*(first-1):first*second;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun numOfPairs(nums:Array<String>,target:String):Int{
        val frequency=nums.groupingBy{
            it
        }.eachCount();
        var answer=0;
        for(split in 1 until target.length){
            val left=target.substring(0,split);
            val right=target.substring(split);
            val first=frequency[left]?:0;
            val second=frequency[right]?:0;
            answer+=if(left==right)first*(first-1) else first*second
        };
        return answer
    }
}

